mapper.select:
SELECT t.id, t.title, t.category, t.unit_price, t.work_location, t.start_time, t.end_time, t.published_at, (SELECT COUNT(*) FROM task_slot s WHERE s.task_id = t.id AND s.status = 'SLOT_AVAILABLE') AS remaining_slots, CASE WHEN EXISTS (SELECT 1 FROM task_slot sa WHERE sa.task_id = t.id AND sa.status = 'SLOT_PENDING_ARBITRATION') THEN 1 ELSE 0 END AS has_settlement_abnormal, 0 AS has_open_dispute FROM task t WHERE t.published_at IS NOT NULL AND t.recruiting_closed = 0 AND EXISTS (SELECT 1 FROM task_slot s2 WHERE s2.task_id = t.id AND s2.status = 'SLOT_AVAILABLE')
AND (t.title LIKE CONCAT('%', #{c.keyword}, '%') OR t.description LIKE CONCAT('%', #{c.keyword}, '%'))
AND t.category = #{c.category}
AND t.unit_price >= #{c.minPrice}
AND t.unit_price <= #{c.maxPrice}
AND t.end_time >= #{c.from}
AND t.start_time <= #{c.to}
AND t.work_location LIKE CONCAT('%', #{c.location}, '%')
ORDER BY t.unit_price ASC, t.id DESC ORDER BY t.unit_price DESC, t.id DESC
ORDER BY t.published_at ASC, t.id DESC ORDER BY t.published_at DESC, t.id DESC
